def can_make_palindrome(N, K, A):
    if N <= 1:
        return "YES"
    if K == 1:
        return "YES" if all(A[i] == A[N - 1 - i] for i in range(N // 2)) else "NO"

    freq = {}
    for num in A:
        freq[num] = freq.get(num, 0) + 1

    odd_count = sum(1 for key in freq if freq[key] % 2 != 0)

    if odd_count <= K:
        return "YES"
    return "NO"

